const results = await Promise.allSettled([
  tools.exec_command({cmd:"python -c \"import rcb_client; help(rcb_client)\"",workdir:"/app",yield_time_ms:10000,max_output_tokens:4500}),
  tools.exec_command({cmd:"sed -n '1,260p' /app/output/gen.py",workdir:"/app",yield_time_ms:10000,max_output_tokens:7000})
]);
for (let i=0;i<results.length;i++){ text(`RESULT ${i+1}`); text(results[i].status==="fulfilled"?results[i].value.output:results[i].reason); }

const a = await tools.view_image({path:"/tmp/robot_base.png"});
